contracts/arc/KletiaArcLending.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

interface IKletiaArcSwap {
    function usdcReserve() external view returns (uint256);
    function tokenReserve() external view returns (uint256);
    function currentCumulativePrices() external view returns (uint256 price0Cumulative, uint256 price1Cumulative, uint32 blockTimestamp);
    function consultKletPrice() external view returns (uint256);
}

/**
 * @title KletiaArcLending
 * @notice Native USDC Borrow/Lending protocol using KLET as collateral.
 * @dev "Agent-Driven DeFi" - Features Aave-like Normalized Indexes and Health Factor.
 */
contract KletiaArcLending is ERC2771Context, ReentrancyGuard {
    IERC20 public immutable kletToken;
    IKletiaArcSwap public swapPool;

    // Constants
    uint256 public constant RAY = 1e27;
    uint256 public constant WAD = 1e18;
    uint256 public constant SECONDS_PER_YEAR = 365 days;

    // Configuration
    uint256 public constant LTV_BIPS = 7000; // 70% Loan-to-Value
    uint256 public constant LIQ_THRESHOLD_BIPS = 8000; // 80% Liquidation Threshold
    uint256 public constant LIQ_PENALTY_BIPS = 500; // 5% bonus to liquidator
    uint256 public constant BIPS_DENOMINATOR = 10000;

    // Interest Rate Model Parameters (in Ray)
    uint256 public constant OPTIMAL_UTILIZATION = 0.8 * 1e27; // 80%
    uint256 public constant BASE_BORROW_RATE = 0;
    uint256 public constant RATE_SLOPE_1 = 0.04 * 1e27; // 4% at optimal
    uint256 public constant RATE_SLOPE_2 = 3.00 * 1e27; // 300% max (Aggressive Algorithmic Balancing)
    uint256 public constant RESERVE_FACTOR = 0.1 * 1e27; // 10%

    // State Variables
    uint256 public liquidityIndex = RAY;
    uint256 public borrowIndex = RAY;
    uint256 public currentLiquidityRate; // Ray
    uint256 public currentBorrowRate; // Ray
    uint40 public lastUpdateTimestamp;

    // TWAP Tracker Variables
    uint256 public twapPrice;
    uint256 public lastPriceCumulative;
    uint32 public lastTwapTimestamp;

    // Balances
    mapping(address => uint256) public collateralBalance; // KLET
    mapping(address => uint256) public scaledSuppliedUSDC; // Scaled Native USDC
    mapping(address => uint256) public scaledBorrowedUSDC; // Scaled Native USDC

    uint256 public scaledTotalUSDCSupplied;
    uint256 public scaledTotalUSDCBorrowed;

    event CollateralAdded(address indexed user, uint256 amount);
    event CollateralRemoved(address indexed user, uint256 amount);
    event USDCBorrowed(address indexed user, uint256 amount);
    event USDCRepaid(address indexed user, uint256 amount);
    event Liquidated(address indexed liquidator, address indexed target, uint256 debtRepaid, uint256 collateralSeized);

    constructor(
        address trustedForwarder,
        address _kletToken,
        address _swapPool
    ) ERC2771Context(trustedForwarder) {
        kletToken = IERC20(_kletToken);
        swapPool = IKletiaArcSwap(_swapPool);
        lastUpdateTimestamp = uint40(block.timestamp);
    }

    // Allow Native USDC supply to the pool
    receive() external payable {
        _updateState();
        _updateTWAP();
        uint256 amount = msg.value;
        uint256 scaledAmount = rayDiv(amount, liquidityIndex);
        scaledTotalUSDCSupplied += scaledAmount;
        scaledSuppliedUSDC[_msgSender()] += scaledAmount;
        _updateRates();
    }

    modifier updateStateAndRates() {
        _updateState();
        _updateTWAP();
        _;
        _updateRates();
    }

    /**
     * @notice Supplies Native USDC liquidity to the protocol
     */
    function supplyUSDC() external payable nonReentrant updateStateAndRates {
        require(msg.value > 0, "KletiaArcLending: Zero supply");
        uint256 scaledAmount = rayDiv(msg.value, liquidityIndex);
        scaledTotalUSDCSupplied += scaledAmount;
        scaledSuppliedUSDC[_msgSender()] += scaledAmount;
    }

    /**
     * @notice Withdraw supplied Native USDC
     */
    function withdrawUSDC(uint256 amount) external nonReentrant updateStateAndRates {
        require(amount > 0, "KletiaArcLending: Zero withdraw");
        address user = _msgSender();

        uint256 userBalance = rayMul(scaledSuppliedUSDC[user], liquidityIndex);
        require(userBalance >= amount, "KletiaArcLending: Insufficient supplied balance");
        require(address(this).balance >= amount, "KletiaArcLending: Insufficient pool liquidity");

        uint256 scaledAmount = rayDiv(amount, liquidityIndex);
        unchecked {
            scaledSuppliedUSDC[user] -= scaledAmount;
            scaledTotalUSDCSupplied -= scaledAmount;
        }

        (bool success, ) = payable(user).call{value: amount}("");
        require(success, "KletiaArcLending: Transfer failed");
    }

    /**
     * @notice Deposit KLET token as collateral
     */
    function depositCollateral(uint256 amount) external nonReentrant {
        require(amount > 0, "KletiaArcLending: Zero deposit");
        address user = _msgSender();

        require(kletToken.transferFrom(user, address(this), amount), "KletiaArcLending: Transfer failed");
        collateralBalance[user] += amount;

        emit CollateralAdded(user, amount);
    }

    /**
     * @notice Withdraw KLET collateral
     */
    function withdrawCollateral(uint256 amount) external nonReentrant updateStateAndRates {
        address user = _msgSender();
        require(amount > 0 && amount <= collateralBalance[user], "KletiaArcLending: Invalid amount");

        unchecked {
            collateralBalance[user] -= amount;
        }

        // Check if healthy
        require(healthFactor(user) >= WAD, "KletiaArcLending: Health factor too low");

        require(kletToken.transfer(user, amount), "KletiaArcLending: Transfer failed");
        emit CollateralRemoved(user, amount);
    }

    /**
     * @notice Borrow Native USDC against KLET collateral
     */
    function borrow(uint256 borrowAmount) external nonReentrant updateStateAndRates {
        require(borrowAmount > 0, "KletiaArcLending: Zero borrow");
        address user = _msgSender();

        require(address(this).balance >= borrowAmount, "KletiaArcLending: Insufficient pool liquidity");

        uint256 scaledAmount = rayDiv(borrowAmount, borrowIndex);
        scaledBorrowedUSDC[user] += scaledAmount;
        scaledTotalUSDCBorrowed += scaledAmount;

        // Check LTV
        uint256 maxBorrow = _getMaxBorrow(user);
        uint256 currentDebt = rayMul(scaledBorrowedUSDC[user], borrowIndex);
        require(currentDebt <= maxBorrow, "KletiaArcLending: Exceeds max borrow LTV");

        (bool success, ) = payable(user).call{value: borrowAmount}("");
        require(success, "KletiaArcLending: USDC transfer failed");

        emit USDCBorrowed(user, borrowAmount);
    }

    /**
     * @notice Repay Native USDC debt
     */
    function repay() external payable nonReentrant updateStateAndRates {
        uint256 repayAmount = msg.value;
        address user = _msgSender();
        require(repayAmount > 0, "KletiaArcLending: Zero repay");

        uint256 currentDebt = rayMul(scaledBorrowedUSDC[user], borrowIndex);

        if (repayAmount > currentDebt) {
            uint256 excess;
            unchecked { excess = repayAmount - currentDebt; }
            scaledBorrowedUSDC[user] = 0;
            unchecked { scaledTotalUSDCBorrowed -= rayDiv(currentDebt, borrowIndex); }

            (bool success, ) = payable(user).call{value: excess}("");
            require(success, "KletiaArcLending: Refund failed");
        } else {
            uint256 scaledAmount = rayDiv(repayAmount, borrowIndex);
            unchecked {
                scaledBorrowedUSDC[user] -= scaledAmount;
                scaledTotalUSDCBorrowed -= scaledAmount;
            }
        }

        emit USDCRepaid(user, repayAmount);
    }

    /**
     * @notice Liquidate an unhealthy position.
     */
    function liquidate(address target) external payable nonReentrant updateStateAndRates {
        address liquidator = _msgSender();
        require(target != liquidator, "KletiaArcLending: Cannot liquidate self");
        require(healthFactor(target) < WAD, "KletiaArcLending: Position is healthy");

        uint256 currentDebt = rayMul(scaledBorrowedUSDC[target], borrowIndex);

        uint256 kletPrice = _getKletPrice();
        uint256 kletRequired = (currentDebt * WAD) / kletPrice;
        uint256 kletToSeize = kletRequired + ((kletRequired * LIQ_PENALTY_BIPS) / BIPS_DENOMINATOR);

        uint256 userCollateral = collateralBalance[target];
        uint256 debtToRepay = currentDebt;

        if (kletToSeize > userCollateral) {
            kletToSeize = userCollateral; 
            uint256 penaltyFactor = WAD + (WAD * LIQ_PENALTY_BIPS) / BIPS_DENOMINATOR;
            debtToRepay = (userCollateral * kletPrice) / penaltyFactor;
        }

        require(msg.value >= debtToRepay, "KletiaArcLending: Insufficient repayment");
        uint256 excess;
        unchecked { excess = msg.value - debtToRepay; }

        unchecked {
            scaledBorrowedUSDC[target] -= rayDiv(debtToRepay, borrowIndex);
            scaledTotalUSDCBorrowed -= rayDiv(debtToRepay, borrowIndex);
            collateralBalance[target] -= kletToSeize;
        }

        require(kletToken.transfer(liquidator, kletToSeize), "KletiaArcLending: Collateral transfer failed");

        if (excess > 0) {
            (bool success, ) = payable(liquidator).call{value: excess}("");
            require(success, "KletiaArcLending: Refund failed");
        }

        emit Liquidated(liquidator, target, debtToRepay, kletToSeize);
    }

    // --- Aave Math & Core ---

    function _updateState() internal {
        uint40 currentTimestamp = uint40(block.timestamp);
        if (currentTimestamp == lastUpdateTimestamp) return;

        if (scaledTotalUSDCBorrowed > 0) {
            uint256 timeDelta;
            unchecked { timeDelta = currentTimestamp - lastUpdateTimestamp; }

            // Linear interest for liquidity index
            uint256 cumulatedLiquidityInterest = RAY + ((currentLiquidityRate * timeDelta) / SECONDS_PER_YEAR);
            liquidityIndex = rayMul(liquidityIndex, cumulatedLiquidityInterest);

            // Binomial approximation for borrow index
            uint256 ratePerSecond = currentBorrowRate / SECONDS_PER_YEAR;
            uint256 basePowerTwo = rayMul(ratePerSecond, ratePerSecond);
            uint256 secondTerm;
            unchecked { secondTerm = (timeDelta * (timeDelta - 1) * basePowerTwo) / 2; }
            uint256 cumulatedBorrowInterest = RAY + (ratePerSecond * timeDelta) + secondTerm;
            borrowIndex = rayMul(borrowIndex, cumulatedBorrowInterest);
        }

        lastUpdateTimestamp = currentTimestamp;
    }

    function _updateTWAP() internal {
        uint256 currentCumulative = 0;
        uint32 blockTimestamp = 0;

        try swapPool.currentCumulativePrices() returns (uint256 val0, uint256 /*val1*/, uint32 ts) {
            currentCumulative = val0;
            blockTimestamp = ts;
        } catch {
            return;
        }

        if (blockTimestamp == lastTwapTimestamp) return;
        uint32 timeElapsed = blockTimestamp - lastTwapTimestamp;

        if (timeElapsed > 0 && lastTwapTimestamp != 0) {
            twapPrice = (currentCumulative - lastPriceCumulative) / timeElapsed;
        } else if (twapPrice == 0) {
            // First time init: fallback to spot
            twapPrice = swapPool.consultKletPrice();
        }

        lastPriceCumulative = currentCumulative;
        lastTwapTimestamp = blockTimestamp;
    }

    function _updateRates() internal {
        uint256 totalDebt = rayMul(scaledTotalUSDCBorrowed, borrowIndex);
        uint256 totalLiquidity = address(this).balance; // Available liquidity

        if (totalDebt == 0) {
            currentBorrowRate = BASE_BORROW_RATE;
            currentLiquidityRate = 0;
            return;
        }

        uint256 utilizationRate = rayDiv(totalDebt, totalDebt + totalLiquidity);

        if (utilizationRate <= OPTIMAL_UTILIZATION) {
            currentBorrowRate = BASE_BORROW_RATE + rayMul(
                rayDiv(utilizationRate, OPTIMAL_UTILIZATION),
                RATE_SLOPE_1
            );
        } else {
            uint256 excessUtilizationRate;
            unchecked {
                excessUtilizationRate = rayDiv(
                    utilizationRate - OPTIMAL_UTILIZATION,
                    RAY - OPTIMAL_UTILIZATION
                );
            }
            currentBorrowRate = BASE_BORROW_RATE + RATE_SLOPE_1 + rayMul(
                excessUtilizationRate,
                RATE_SLOPE_2
            );
        }

        currentLiquidityRate = rayMul(rayMul(currentBorrowRate, utilizationRate), RAY - RESERVE_FACTOR);
    }

    // --- Internal View Helpers ---

    function _getKletPrice() public view returns (uint256) {
        if (twapPrice > 0) return twapPrice;
        // Fallback for extreme edge cases if TWAP hasn't initialized
        return swapPool.consultKletPrice();
    }

    function _getMaxBorrow(address user) public view returns (uint256) {
        uint256 colKlet = collateralBalance[user];
        if (colKlet == 0) return 0;
        uint256 kletPrice = _getKletPrice();
        uint256 colValueUSDC = (colKlet * kletPrice) / WAD;
        return (colValueUSDC * LTV_BIPS) / BIPS_DENOMINATOR;
    }

    /**
     * @notice Calculate Health Factor for a user
     * @dev HF = (Collateral Value * Liquidation Threshold) / Total Debt
     * If HF < 1e18 (WAD), position can be liquidated.
     */
    function healthFactor(address user) public view returns (uint256) {
        uint256 currentDebt = rayMul(scaledBorrowedUSDC[user], borrowIndex);
        if (currentDebt == 0) return type(uint256).max;

        uint256 colKlet = collateralBalance[user];
        if (colKlet == 0) return 0;

        uint256 kletPrice = _getKletPrice();
        uint256 colValueUSDC = (colKlet * kletPrice) / WAD;

        uint256 thresholdLimit = (colValueUSDC * LIQ_THRESHOLD_BIPS) / BIPS_DENOMINATOR;
        return (thresholdLimit * WAD) / currentDebt;
    }

    // --- Ray Math Helpers ---

    function rayMul(uint256 a, uint256 b) internal pure returns (uint256) {
        return (a * b + (RAY / 2)) / RAY;
    }

    function rayDiv(uint256 a, uint256 b) internal pure returns (uint256) {
        return (a * RAY + (b / 2)) / b;
    }

    // --- External Views ---

    function getSuppliedBalance(address user) external view returns (uint256) {
        return rayMul(scaledSuppliedUSDC[user], liquidityIndex);
    }

    function getBorrowedBalance(address user) external view returns (uint256) {
        return rayMul(scaledBorrowedUSDC[user], borrowIndex);
    }
}

contracts/arc/KletiaArcMemoTransfer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/metatx/ERC2771Context.sol";

/**
 * @title KletiaArcMemoTransfer
 * @author Kletia Team
 * @notice Native USDC transfer contract with on-chain memo/reference strings.
 * @dev Every transfer receives a unique auto-incrementing ID and stores a
 *      memo that can be queried later. Transfer history is indexed by both
 *      sender and recipient addresses.
 *
 *      This leverages ARC Network's low-cost storage to keep memo data
 *      on-chain for auditability and compliance.
 *
 *      Chain ID: 311614
 */
contract KletiaArcMemoTransfer is ERC2771Context {
    // ──────────────────────── State ────────────────────────

    address public owner;

    /// @notice Auto-incrementing transfer ID counter.
    uint256 public nextTransferId;

    struct TransferRecord {
        uint256 id;
        address from;
        address to;
        uint256 amount;
        string memo;
        uint256 timestamp;
    }

    /// @notice Transfer ID → full record.
    mapping(uint256 => TransferRecord) public transfers;

    /// @notice Address → list of transfer IDs the address was involved in (as sender).
    mapping(address => uint256[]) private _sentTransfers;

    /// @notice Address → list of transfer IDs the address was involved in (as recipient).
    mapping(address => uint256[]) private _receivedTransfers;

    // Reentrancy guard
    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;
    uint256 private _status;

    // ──────────────────────── Events ───────────────────────

    event MemoTransfer(
        address indexed from,
        address indexed to,
        uint256 amount,
        string memo,
        uint256 indexed transferId
    );
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // ──────────────────────── Modifiers ────────────────────

    modifier onlyOwner() {
        require(_msgSender() == owner, "KletiaArcMemoTransfer: caller is not the owner");
        _;
    }

    modifier nonReentrant() {
        require(_status != _ENTERED, "KletiaArcMemoTransfer: reentrant call");
        _status = _ENTERED;
        _;
        _status = _NOT_ENTERED;
    }

    // ──────────────────────── Constructor ──────────────────

    constructor(address trustedForwarder) ERC2771Context(trustedForwarder) {
        owner = _msgSender();
        _status = _NOT_ENTERED;
        emit OwnershipTransferred(address(0), _msgSender());
    }

    // ──────────────────────── Core ─────────────────────────

    /**
     * @notice Transfer Native USDC to `to` with an attached memo.
     * @param to        Recipient address.
     * @param memo      Reference string (invoice number, note, etc.).
     * @return transferId The unique ID assigned to this transfer.
     */
    function transferWithMemo(
        address to,
        string calldata memo
    ) external payable nonReentrant returns (uint256 transferId) {
        uint256 amount = msg.value;
        require(to != address(0), "KletiaArcMemoTransfer: invalid recipient");
        require(to != _msgSender(), "KletiaArcMemoTransfer: cannot transfer to self");
        require(amount > 0, "KletiaArcMemoTransfer: amount must be > 0");
        require(bytes(memo).length > 0, "KletiaArcMemoTransfer: memo cannot be empty");
        require(bytes(memo).length <= 256, "KletiaArcMemoTransfer: memo too long");

        transferId = nextTransferId++;

        // Forward Native USDC to recipient
        (bool success, ) = payable(to).call{value: amount}("");
        require(success, "KletiaArcMemoTransfer: Native USDC transfer failed");

        // Store record
        transfers[transferId] = TransferRecord({
            id: transferId,
            from: _msgSender(),
            to: to,
            amount: amount,
            memo: memo,
            timestamp: block.timestamp
        });

        _sentTransfers[_msgSender()].push(transferId);
        _receivedTransfers[to].push(transferId);

        emit MemoTransfer(_msgSender(), to, amount, memo, transferId);
    }

    // ──────────────────────── Views ────────────────────────

    /**
     * @notice Get a transfer record by its ID.
     */
    function getTransfer(uint256 transferId) external view returns (TransferRecord memory) {
        require(transferId < nextTransferId, "KletiaArcMemoTransfer: transfer does not exist");
        return transfers[transferId];
    }

    /**
     * @notice Get the memo for a specific transfer.
     */
    function getMemo(uint256 transferId) external view returns (string memory) {
        require(transferId < nextTransferId, "KletiaArcMemoTransfer: transfer does not exist");
        return transfers[transferId].memo;
    }

    /**
     * @notice Get all transfer IDs sent by `addr`.
     */
    function getSentTransferIds(address addr) external view returns (uint256[] memory) {
        return _sentTransfers[addr];
    }

    /**
     * @notice Get all transfer IDs received by `addr`.
     */
    function getReceivedTransferIds(address addr) external view returns (uint256[] memory) {
        return _receivedTransfers[addr];
    }

    /**
     * @notice Get the count of transfers sent by `addr`.
     */
    function sentTransferCount(address addr) external view returns (uint256) {
        return _sentTransfers[addr].length;
    }

    /**
     * @notice Get the count of transfers received by `addr`.
     */
    function receivedTransferCount(address addr) external view returns (uint256) {
        return _receivedTransfers[addr].length;
    }

    /**
     * @notice Get the total number of transfers ever made.
     */
    function totalTransfers() external view returns (uint256) {
        return nextTransferId;
    }

    // ──────────────────────── Admin ────────────────────────

    /**
     * @notice Transfer contract ownership.
     */
    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "KletiaArcMemoTransfer: invalid new owner");
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }
}

contracts/arc/KletiaArcOTC.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import "./IERC20.sol";

contract KletiaArcOTC is ERC2771Context {
    struct Order {
        address maker;
        address tokenIn;
        address tokenOut;
        uint256 amountIn;
        uint256 minAmountOut;
        bool isActive;
    }

    uint256 public orderCount;
    mapping(uint256 => Order) public orders;

    event OrderCreated(uint256 indexed orderId, address indexed maker, address tokenIn, address tokenOut, uint256 amountIn, uint256 minAmountOut);
    event OrderFilled(uint256 indexed orderId, address indexed taker, uint256 amountOut);

    constructor(address trustedForwarder) ERC2771Context(trustedForwarder) {}

    function createOrder(address _tokenIn, address _tokenOut, uint256 _amountIn, uint256 _minAmountOut) external returns (uint256) {
        require(_amountIn > 0, "Amount must be > 0");
        IERC20(_tokenIn).transferFrom(_msgSender(), address(this), _amountIn);

        orderCount++;
        orders[orderCount] = Order({
            maker: _msgSender(),
            tokenIn: _tokenIn,
            tokenOut: _tokenOut,
            amountIn: _amountIn,
            minAmountOut: _minAmountOut,
            isActive: true
        });

        emit OrderCreated(orderCount, _msgSender(), _tokenIn, _tokenOut, _amountIn, _minAmountOut);
        return orderCount;
    }

    function fillOrder(uint256 _orderId) external payable {
        Order storage order = orders[_orderId];
        require(order.isActive, "Order not active");

        if (order.tokenOut == address(0)) {
            // TokenOut is Native (USDC on Arc Testnet)
            require(msg.value >= order.minAmountOut, "Insufficient native value");
            payable(order.maker).transfer(msg.value);
        } else {
            // TokenOut is ERC20
            IERC20(order.tokenOut).transferFrom(_msgSender(), order.maker, order.minAmountOut);
        }

        // Send the locked tokenIn to the taker
        IERC20(order.tokenIn).transfer(_msgSender(), order.amountIn);
        order.isActive = false;

        emit OrderFilled(_orderId, _msgSender(), order.minAmountOut);
    }

    function cancelOrder(uint256 _orderId) external {
        Order storage order = orders[_orderId];
        require(order.isActive, "Order not active");
        require(order.maker == _msgSender(), "Not your order");

        order.isActive = false;
        IERC20(order.tokenIn).transfer(_msgSender(), order.amountIn);
    }
}

