// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/metatx/ERC2771Context.sol";

/**
 * @title KletiaArcStaking
 * @author Kletia Team
 * @notice Native USDC staking contract.
 * @dev Users stake Native USDC and earn Native USDC rewards based on APR.
 *      Chain ID: 311614
 */
contract KletiaArcStaking is ERC2771Context {
    // ──────────────────────── State ────────────────────────

    address public owner;

    /// @notice Annual Percentage Rate in basis points (e.g., 500 = 5%).
    uint256 public aprBps;

    /// @notice Cooldown period before unstaked funds can be claimed (default: 7 days).
    uint256 public cooldownPeriod;

    /// @notice Total USDC staked across all users.
    uint256 public totalStaked;

    /// @notice Total USDC available in the reward pool.
    uint256 public rewardPoolBalance;

    uint256 private constant BPS_DENOMINATOR = 10000;
    uint256 private constant SECONDS_PER_YEAR = 31536000;
    uint256 private constant MAX_APR_BPS = 3000; // 30%
    uint256 private constant MIN_STAKE = 1; // 1 unit (wei-equivalent for native USDC)

    struct StakerInfo {
        uint256 stakedAmount;
        uint256 stakingTimestamp;
        uint256 accruedRewards;
        uint256 pendingUnstake;
        uint256 unstakeRequestTime;
    }

    /// @notice Per-user staking data.
    mapping(address => StakerInfo) public stakers;

    // ──────────────────────── Reentrancy Guard ─────────────

    bool private _locked;

    modifier nonReentrant() {
        require(!_locked, "KletiaArcStaking: reentrant call");
        _locked = true;
        _;
        _locked = false;
    }

    // ──────────────────────── Events ───────────────────────

    event Staked(address indexed user, uint256 amount, uint256 totalUserStake);
    event UnstakeRequested(address indexed user, uint256 amount, uint256 claimableAfter);
    event Unstaked(address indexed user, uint256 amount);
    event RewardsClaimed(address indexed user, uint256 amount);
    event APRUpdated(uint256 oldAPR, uint256 newAPR);
    event RewardsFunded(address indexed funder, uint256 amount, uint256 newPoolBalance);
    event CooldownUpdated(uint256 oldCooldown, uint256 newCooldown);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // ──────────────────────── Modifiers ────────────────────

    modifier onlyOwner() {
        require(_msgSender() == owner, "KletiaArcStaking: caller is not the owner");
        _;
    }

    // ──────────────────────── Constructor ──────────────────

    /**
     * @param _aprBps          Initial APR in basis points (e.g., 500 = 5%, max 3000 = 30%).
     * @param _cooldownPeriod  Initial cooldown period in seconds (e.g., 604800 = 7 days).
     */
    constructor(address trustedForwarder, uint256 _aprBps, uint256 _cooldownPeriod) ERC2771Context(trustedForwarder) {
        require(_aprBps <= MAX_APR_BPS, "KletiaArcStaking: APR too high");
        require(_cooldownPeriod > 0, "KletiaArcStaking: cooldown must be > 0");

        owner = _msgSender();
        aprBps = _aprBps;
        cooldownPeriod = _cooldownPeriod;

        emit OwnershipTransferred(address(0), _msgSender());
        emit APRUpdated(0, _aprBps);
    }

    // ──────────────────────── User Functions ───────────────

    /**
     * @notice Stake Native USDC into the staking pool.
     * @dev If user already has a stake, accrued rewards are snapshotted
     *      before updating their stake.
     */
    function stake() external payable nonReentrant {
        uint256 amount = msg.value;
        require(amount >= MIN_STAKE, "KletiaArcStaking: amount too small");

        StakerInfo storage s = stakers[_msgSender()];

        // Snapshot accrued rewards on existing stake before updating
        if (s.stakedAmount > 0) {
            s.accruedRewards += _calculateRewards(s.stakedAmount, s.stakingTimestamp);
        }

        s.stakedAmount += amount;
        s.stakingTimestamp = block.timestamp;
        totalStaked += amount;

        emit Staked(_msgSender(), amount, s.stakedAmount);
    }

    /**
     * @notice Request to unstake a given amount. Starts the cooldown timer.
     * @dev Only one pending unstake at a time. User must claim or cancel before
     *      requesting a new unstake. Accrued rewards are snapshotted.
     * @param amount The amount of staked USDC to unstake.
     */
    function unstake(uint256 amount) external nonReentrant {
        StakerInfo storage s = stakers[_msgSender()];

        require(amount > 0, "KletiaArcStaking: amount must be > 0");
        require(s.stakedAmount >= amount, "KletiaArcStaking: insufficient staked balance");
        require(s.pendingUnstake == 0, "KletiaArcStaking: existing unstake pending");

        // Snapshot rewards before reducing stake
        s.accruedRewards += _calculateRewards(s.stakedAmount, s.stakingTimestamp);

        s.stakedAmount -= amount;
        s.stakingTimestamp = block.timestamp;
        s.pendingUnstake = amount;
        s.unstakeRequestTime = block.timestamp;
        totalStaked -= amount;

        emit UnstakeRequested(_msgSender(), amount, block.timestamp + cooldownPeriod);
    }

    /**
     * @notice Claim unstaked USDC after the cooldown period has elapsed.
     */
    function claimUnstaked() external nonReentrant {
        StakerInfo storage s = stakers[_msgSender()];

        require(s.pendingUnstake > 0, "KletiaArcStaking: no pending unstake");
        require(
            block.timestamp >= s.unstakeRequestTime + cooldownPeriod,
            "KletiaArcStaking: cooldown not elapsed"
        );

        uint256 payout = s.pendingUnstake;

        // Clear state before transfer (CEI pattern)
        s.pendingUnstake = 0;
        s.unstakeRequestTime = 0;

        require(
            address(this).balance >= payout,
            "KletiaArcStaking: insufficient contract balance"
        );

        (bool success, ) = payable(_msgSender()).call{value: payout}("");
        require(success, "KletiaArcStaking: USDC native transfer failed");

        emit Unstaked(_msgSender(), payout);
    }

    /**
     * @notice Claim all accrued staking rewards.
     * @dev Rewards are paid from the reward pool. Reverts if pool is insufficient.
     */
    function claimRewards() external nonReentrant {
        StakerInfo storage s = stakers[_msgSender()];

        uint256 rewards = s.accruedRewards;
        if (s.stakedAmount > 0) {
            rewards += _calculateRewards(s.stakedAmount, s.stakingTimestamp);
            s.stakingTimestamp = block.timestamp;
        }

        require(rewards > 0, "KletiaArcStaking: no rewards to claim");
        require(rewardPoolBalance >= rewards, "KletiaArcStaking: insufficient reward pool");

        // Clear state before transfer (CEI pattern)
        s.accruedRewards = 0;
        rewardPoolBalance -= rewards;

        (bool success, ) = payable(_msgSender()).call{value: rewards}("");
        require(success, "KletiaArcStaking: USDC native transfer failed");

        emit RewardsClaimed(_msgSender(), rewards);
    }

    // ──────────────────────── Admin ────────────────────────

    /**
     * @notice Update the APR rate.
     * @param newAprBps New APR in basis points (max 30%).
     */
    function setAPR(uint256 newAprBps) external onlyOwner {
        require(newAprBps <= MAX_APR_BPS, "KletiaArcStaking: APR too high");
        uint256 oldApr = aprBps;
        aprBps = newAprBps;
        emit APRUpdated(oldApr, newAprBps);
    }

    /**
     * @notice Update the cooldown period.
     * @param newCooldown New cooldown period in seconds.
     */
    function setCooldownPeriod(uint256 newCooldown) external onlyOwner {
        require(newCooldown > 0, "KletiaArcStaking: cooldown must be > 0");
        uint256 oldCooldown = cooldownPeriod;
        cooldownPeriod = newCooldown;
        emit CooldownUpdated(oldCooldown, newCooldown);
    }

    /**
     * @notice Fund the reward pool with Native USDC.
     */
    function fundRewards() external payable onlyOwner {
        require(msg.value > 0, "KletiaArcStaking: amount must be > 0");
        rewardPoolBalance += msg.value;
        emit RewardsFunded(_msgSender(), msg.value, rewardPoolBalance);
    }

    /**
     * @notice Transfer contract ownership.
     */
    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "KletiaArcStaking: invalid new owner");
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }

    // ──────────────────────── Views ────────────────────────

    /**
     * @notice Returns the pending (unclaimed) rewards for a user.
     */
    function pendingRewards(address user) external view returns (uint256) {
        StakerInfo storage s = stakers[user];
        uint256 rewards = s.accruedRewards;
        if (s.stakedAmount > 0) {
            rewards += _calculateRewards(s.stakedAmount, s.stakingTimestamp);
        }
        return rewards;
    }

    /**
     * @notice Returns full staker information for a user.
     */
    function getStakerInfo(address user)
        external
        view
        returns (
            uint256 stakedAmount,
            uint256 stakingTimestamp,
            uint256 accruedRewards,
            uint256 pendingUnstake,
            uint256 unstakeRequestTime,
            uint256 cooldownRemaining
        )
    {
        StakerInfo storage s = stakers[user];
        stakedAmount = s.stakedAmount;
        stakingTimestamp = s.stakingTimestamp;
        pendingUnstake = s.pendingUnstake;
        unstakeRequestTime = s.unstakeRequestTime;

        // Include live accrued rewards
        accruedRewards = s.accruedRewards;
        if (s.stakedAmount > 0) {
            accruedRewards += _calculateRewards(s.stakedAmount, s.stakingTimestamp);
        }

        // Calculate remaining cooldown
        if (s.pendingUnstake > 0) {
            uint256 unlockTime = s.unstakeRequestTime + cooldownPeriod;
            cooldownRemaining = block.timestamp >= unlockTime ? 0 : unlockTime - block.timestamp;
        }
    }

    /**
     * @notice Returns the contract's total Native USDC balance.
     */
    function contractBalance() external view returns (uint256) {
        return address(this).balance;
    }

    // ──────────────────────── Internal ─────────────────────

    /**
     * @dev Calculates simple rewards accrued since `since` on `staked`.
     *      rewards = staked * aprBps * elapsed / (BPS_DENOMINATOR * SECONDS_PER_YEAR)
     */
    function _calculateRewards(uint256 staked, uint256 since) internal view returns (uint256) {
        if (since == 0 || staked == 0) return 0;
        uint256 elapsed = block.timestamp - since;
        return (staked * aprBps * elapsed) / (BPS_DENOMINATOR * SECONDS_PER_YEAR);
    }
}

contracts/arc/KletiaArcSwap.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/metatx/ERC2771Context.sol";

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title KletiaArcSwap (AMM version)
 * @notice Constant Product AMM (X * Y = K) for Native USDC (gas token) and an ERC20 Token.
 * @dev Mints LP tokens to liquidity providers.
 */
contract KletiaArcSwap is ERC2771Context, ERC20, ReentrancyGuard {
    using Math for uint256;

    function _msgSender() internal view virtual override(Context, ERC2771Context) returns (address) {
        return ERC2771Context._msgSender();
    }

    function _msgData() internal view virtual override(Context, ERC2771Context) returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength() internal view virtual override(Context, ERC2771Context) returns (uint256) {
        return ERC2771Context._contextSuffixLength();
    }

    IERC20 public immutable token;

    uint256 public reserveUSDC;
    uint256 public reserveToken;

    uint32 public blockTimestampLast;
    uint256 public price0CumulativeLast; // USDC per Token cumulative (represented as WAD)
    uint256 public price1CumulativeLast; // Token per USDC cumulative (represented as WAD)

    event Swapped(
        address indexed user,
        address indexed fromToken, // address(0) means Native USDC
        address indexed toToken,
        uint256 amountIn,
        uint256 amountOut
    );
    event LiquidityAdded(address indexed provider, uint256 usdcAmount, uint256 tokenAmount, uint256 lpMinted);
    event LiquidityRemoved(address indexed provider, uint256 usdcAmount, uint256 tokenAmount, uint256 lpBurned);

    constructor(address trustedForwarder, address _token) ERC20("Kletia Arc LP Token", "KLET-USDC-LP")  ERC2771Context(trustedForwarder) {
        require(_token != address(0), "Invalid token address");
        token = IERC20(_token);
    }

    receive() external payable {
        // Only accept native USDC via addLiquidity or swap
    }

    /**
     * @notice Returns the Native USDC balance held in this contract.
     */
    function usdcReserve() external view returns (uint256) {
        return reserveUSDC;
    }

    /**
     * @notice Returns the custom token balance held in this contract.
     */
    function tokenReserve() external view returns (uint256) {
        return reserveToken;
    }

    function consultKletPrice() external view returns (uint256) {
        if (reserveToken == 0) return 0;
        return (reserveUSDC * 1e18) / reserveToken;
    }

    /**
     * @notice Fetch the extrapolated TWAP accumulators to the current block.
     * @dev Required because price0CumulativeLast is only updated on actual trades.
     */
    function currentCumulativePrices() public view returns (uint256 price0Cumulative, uint256 price1Cumulative, uint32 blockTimestamp) {
        price0Cumulative = price0CumulativeLast;
        price1Cumulative = price1CumulativeLast;
        blockTimestamp = uint32(block.timestamp % 2**32);
        uint32 timeElapsed;
        unchecked { timeElapsed = blockTimestamp - blockTimestampLast; }
        if (timeElapsed > 0 && reserveUSDC != 0 && reserveToken != 0) {
            unchecked {
                price0Cumulative += ((reserveUSDC * 1e18) / reserveToken) * timeElapsed;
                price1Cumulative += ((reserveToken * 1e18) / reserveUSDC) * timeElapsed;
            }
        }
    }

    function _update(uint256 balanceUSDC, uint256 balanceToken) private {
        uint32 blockTimestamp = uint32(block.timestamp % 2**32);
        uint32 timeElapsed;
        unchecked { timeElapsed = blockTimestamp - blockTimestampLast; }
        if (timeElapsed > 0 && reserveUSDC != 0 && reserveToken != 0) {
            unchecked {
                price0CumulativeLast += ((reserveUSDC * 1e18) / reserveToken) * timeElapsed;
                price1CumulativeLast += ((reserveToken * 1e18) / reserveUSDC) * timeElapsed;
            }
        }
        reserveUSDC = balanceUSDC;
        reserveToken = balanceToken;
        blockTimestampLast = blockTimestamp;
    }

    /**
     * @notice Adds liquidity to the pool.
     * @param maxTokenAmount Maximum amount of tokens to add.
     * @return tokenAmount Exact amount of tokens added.
     * @return lpMinted Amount of LP tokens minted.
     */
    function addLiquidity(uint256 maxTokenAmount) external payable nonReentrant returns (uint256 tokenAmount, uint256 lpMinted) {
        uint256 usdcAmount = msg.value;
        require(usdcAmount > 0, "Zero USDC added");
        require(maxTokenAmount > 0, "Zero token added");

        if (totalSupply() == 0) {
            tokenAmount = maxTokenAmount;
            lpMinted = Math.sqrt(usdcAmount * tokenAmount);
            require(lpMinted > 1000, "Zero LP minted");
            _mint(address(0xdead), 1000); // Lock minimum liquidity
            lpMinted -= 1000;
        } else {
            uint256 tokenOptimal = (usdcAmount * reserveToken) / reserveUSDC;
            require(tokenOptimal <= maxTokenAmount, "Too much token required");
            tokenAmount = tokenOptimal;
            lpMinted = Math.min(
                (usdcAmount * totalSupply()) / reserveUSDC,
                (tokenAmount * totalSupply()) / reserveToken
            );
        }

        require(token.transferFrom(_msgSender(), address(this), tokenAmount), "Token transfer failed");

        _mint(_msgSender(), lpMinted);

        _update(address(this).balance, token.balanceOf(address(this)));

        emit LiquidityAdded(_msgSender(), usdcAmount, tokenAmount, lpMinted);
    }

    /**
     * @notice Removes liquidity from the pool.
     * @param lpAmount Amount of LP tokens to burn.
     */
    function removeLiquidity(uint256 lpAmount) external nonReentrant returns (uint256 usdcAmount, uint256 tokenAmount) {
        require(lpAmount > 0, "Zero LP burned");
        require(balanceOf(_msgSender()) >= lpAmount, "Insufficient LP balance");

        usdcAmount = (lpAmount * reserveUSDC) / totalSupply();
        tokenAmount = (lpAmount * reserveToken) / totalSupply();

        _burn(_msgSender(), lpAmount);

        (bool success, ) = payable(_msgSender()).call{value: usdcAmount}("");
        require(success, "USDC transfer failed");

        require(token.transfer(_msgSender(), tokenAmount), "Token transfer failed");

        _update(address(this).balance, token.balanceOf(address(this)));

        emit LiquidityRemoved(_msgSender(), usdcAmount, tokenAmount, lpAmount);
    }

    /**
     * @notice Swap Native USDC for Token
     */
    function swapUSDCForToken() external payable nonReentrant returns (uint256 tokenAmount) {
        uint256 usdcAmount = msg.value;
        require(usdcAmount > 0, "Zero USDC input");

        uint256 usdcAmountWithFee = usdcAmount * 997;
        uint256 numerator = usdcAmountWithFee * reserveToken;
        uint256 denominator = (reserveUSDC * 1000) + usdcAmountWithFee;
        tokenAmount = numerator / denominator;

        require(tokenAmount > 0, "Zero token output");
        require(token.transfer(_msgSender(), tokenAmount), "Token transfer failed");

        _update(address(this).balance, token.balanceOf(address(this)));

        emit Swapped(_msgSender(), address(0), address(token), usdcAmount, tokenAmount);
    }

    /**
     * @notice Swap Token for Native USDC
     */
    function swapTokenForUSDC(uint256 tokenAmount) external nonReentrant returns (uint256 usdcAmount) {
        require(tokenAmount > 0, "Zero token input");

        uint256 tokenAmountWithFee = tokenAmount * 997;
        uint256 numerator = tokenAmountWithFee * reserveUSDC;
        uint256 denominator = (reserveToken * 1000) + tokenAmountWithFee;
        usdcAmount = numerator / denominator;

        require(usdcAmount > 0, "Zero USDC output");

        require(token.transferFrom(_msgSender(), address(this), tokenAmount), "Token transfer failed");

        (bool success, ) = payable(_msgSender()).call{value: usdcAmount}("");
        require(success, "USDC transfer failed");

        _update(address(this).balance, token.balanceOf(address(this)));

        emit Swapped(_msgSender(), address(token), address(0), tokenAmount, usdcAmount);
    }

    /**
     * @notice Preview the output amount for a Native USDC → Token swap.
     */
    function previewSwapUSDCForToken(uint256 usdcAmount) external view returns (uint256 tokenAmount) {
        if (reserveUSDC == 0 || reserveToken == 0) return 0;
        uint256 usdcAmountWithFee = usdcAmount * 997;
        uint256 numerator = usdcAmountWithFee * reserveToken;
        uint256 denominator = (reserveUSDC * 1000) + usdcAmountWithFee;
        return numerator / denominator;
    }

    /**
     * @notice Preview the output amount for a Token → Native USDC swap.
     */
    function previewSwapTokenForUSDC(uint256 tokenAmount) external view returns (uint256 usdcAmount) {
        if (reserveUSDC == 0 || reserveToken == 0) return 0;
        uint256 tokenAmountWithFee = tokenAmount * 997;
        uint256 numerator = tokenAmountWithFee * reserveUSDC;
        uint256 denominator = (reserveToken * 1000) + tokenAmountWithFee;
        return numerator / denominator;
    }
}

contracts/arc/KletiaArcVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/metatx/ERC2771Context.sol";

/**
 * @title KletiaArcVault
 * @author Kletia Team
 * @notice Native USDC Vault with simple compounding APY for the ARC Network.
 * @dev Users deposit Native USDC (msg.value) and earn interest over time based on an
 *      owner-defined APY. Both principal and interest are paid out in Native USDC.
 *
 *      Chain ID: 311614
 */
contract KletiaArcVault is ERC2771Context {
    // ──────────────────────── State ────────────────────────

    address public owner;

    /// @notice Annual Percentage Yield in basis points (e.g., 500 = 5%).
    uint256 public apyBps;

    uint256 private constant BPS_DENOMINATOR = 10000;
    uint256 private constant SECONDS_PER_YEAR = 31536000;

    struct Deposit {
        uint256 principal;
        uint256 lastAccrualTimestamp;
        uint256 accruedInterest;
    }

    /// @notice Per-user deposit data.
    mapping(address => Deposit) public deposits;

    /// @notice Total principal deposited across all users.
    uint256 public totalDeposited;

    // Reentrancy guard
    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;
    uint256 private _status;

    // ──────────────────────── Events ───────────────────────

    event Deposited(address indexed user, uint256 amount, uint256 totalPrincipal);
    event Withdrawn(address indexed user, uint256 principal, uint256 interest, uint256 totalPayout);
    event EmergencyWithdrawn(address indexed user, uint256 principal, uint256 forfeitedInterest);
    event APYUpdated(uint256 oldAPY, uint256 newAPY);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event VaultFunded(address indexed funder, uint256 amount);

    // ──────────────────────── Modifiers ────────────────────

    modifier onlyOwner() {
        require(_msgSender() == owner, "KletiaArcVault: caller is not the owner");
        _;
    }

    modifier nonReentrant() {
        require(_status != _ENTERED, "KletiaArcVault: reentrant call");
        _status = _ENTERED;
        _;
        _status = _NOT_ENTERED;
    }

    // ──────────────────────── Constructor ──────────────────

    /**
     * @param _apyBps  Initial APY in basis points (e.g., 500 = 5%).
     */
    constructor(address trustedForwarder, uint256 _apyBps) ERC2771Context(trustedForwarder) {
        require(_apyBps <= 5000, "KletiaArcVault: APY too high"); // max 50%

        owner = _msgSender();
        apyBps = _apyBps;
        _status = _NOT_ENTERED;

        emit OwnershipTransferred(address(0), _msgSender());
        emit APYUpdated(0, _apyBps);
    }

    // ──────────────────────── Receive ────────────────────────

    /// @notice Allow contract to receive native USDC directly for funding.
    receive() external payable {
        emit VaultFunded(_msgSender(), msg.value);
    }

    // ──────────────────────── User Functions ───────────────

    /**
     * @notice Deposit Native USDC into the vault.
     * @dev If user has an existing deposit, accrued interest is snapshotted
     *      before the new principal is added.
     */
    function deposit() external payable nonReentrant {
        uint256 amount = msg.value;
        require(amount > 0, "KletiaArcVault: amount must be > 0");

        Deposit storage d = deposits[_msgSender()];

        // Snapshot accrued interest on existing principal before updating
        if (d.principal > 0) {
            d.accruedInterest += _calculateInterest(d.principal, d.lastAccrualTimestamp);
        }

        d.principal += amount;
        d.lastAccrualTimestamp = block.timestamp;
        totalDeposited += amount;

        emit Deposited(_msgSender(), amount, d.principal);
    }

    /**
     * @notice Withdraw full principal + all accrued interest.
     * @dev Reverts if the vault has insufficient Native USDC to pay interest.
     */
    function withdraw() external nonReentrant {
        Deposit storage d = deposits[_msgSender()];
        require(d.principal > 0, "KletiaArcVault: no active deposit");

        uint256 interest = d.accruedInterest + _calculateInterest(d.principal, d.lastAccrualTimestamp);
        uint256 principal = d.principal;
        uint256 totalPayout = principal + interest;

        if (address(this).balance < totalPayout) {
            uint256 availableInterest = address(this).balance > principal ? address(this).balance - principal : 0;
            totalPayout = principal + availableInterest;
            interest = availableInterest;
        }

        // Clear state before transfer (CEI pattern)
        unchecked {
            totalDeposited -= principal;
        }
        d.principal = 0;
        d.accruedInterest = 0;
        d.lastAccrualTimestamp = 0;

        (bool success, ) = payable(_msgSender()).call{value: totalPayout}("");
        require(success, "KletiaArcVault: USDC native transfer failed");

        emit Withdrawn(_msgSender(), principal, interest, totalPayout);
    }

    /**
     * @notice Emergency withdraw principal only — all accrued interest is forfeited.
     */
    function emergencyWithdraw() external nonReentrant {
        Deposit storage d = deposits[_msgSender()];
        require(d.principal > 0, "KletiaArcVault: no active deposit");

        uint256 principal = d.principal;
        uint256 forfeited = d.accruedInterest + _calculateInterest(principal, d.lastAccrualTimestamp);

        // Clear state before transfer
        unchecked {
            totalDeposited -= principal;
        }
        d.principal = 0;
        d.accruedInterest = 0;
        d.lastAccrualTimestamp = 0;

        (bool success, ) = payable(_msgSender()).call{value: principal}("");
        require(success, "KletiaArcVault: USDC native transfer failed");

        emit EmergencyWithdrawn(_msgSender(), principal, forfeited);
    }

    // ──────────────────────── Admin ────────────────────────

    /**
     * @notice Update the APY rate.
     * @param newApyBps New APY in basis points (max 50%).
     */
    function setAPY(uint256 newApyBps) external onlyOwner {
        require(newApyBps <= 5000, "KletiaArcVault: APY too high");
        uint256 oldApy = apyBps;
        apyBps = newApyBps;
        emit APYUpdated(oldApy, newApyBps);
    }

    /**
     * @notice Owner funds the vault with Native USDC to cover interest payments.
     */
    function fundVault() external payable onlyOwner {
        require(msg.value > 0, "KletiaArcVault: amount must be > 0");
        emit VaultFunded(_msgSender(), msg.value);
    }

    /**
     * @notice Transfer contract ownership.
     */
    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "KletiaArcVault: invalid new owner");
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }

    // ──────────────────────── Views ────────────────────────

    /**
     * @notice Returns the pending (unclaimed) interest for a user.
     */
    function pendingInterest(address user) external view returns (uint256) {
        Deposit storage d = deposits[user];
        if (d.principal == 0) return 0;
        return d.accruedInterest + _calculateInterest(d.principal, d.lastAccrualTimestamp);
    }

    /**
     * @notice Returns the total claimable amount (principal + interest).
     */
    function claimableAmount(address user) external view returns (uint256) {
        Deposit storage d = deposits[user];
        if (d.principal == 0) return 0;
        return d.principal + d.accruedInterest + _calculateInterest(d.principal, d.lastAccrualTimestamp);
    }

    /**
     * @notice Returns the vault's total Native USDC balance (principal + reserve for interest).
     */
    function vaultBalance() external view returns (uint256) {
        return address(this).balance;
    }

    // ──────────────────────── Internal ─────────────────────

    /**
     * @dev Calculates simple interest accrued since `since` on `principal`.
     *      interest = principal * apyBps * elapsed / (BPS_DENOMINATOR * SECONDS_PER_YEAR)
     */
    function _calculateInterest(uint256 principal, uint256 since) internal view returns (uint256) {
        if (since == 0 || principal == 0) return 0;
        uint256 elapsed;
        unchecked {
            elapsed = block.timestamp - since;
        }
        return (principal * apyBps * elapsed) / (BPS_DENOMINATOR * SECONDS_PER_YEAR);
    }
}

contracts/KletiaSmartRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title KletiaSmartRouter
 * @dev Kletia Omni-Engine için Güvenli Yönlendirici (Blockaid-Proof)
 * Bu kontrat, %0.1 protokol komisyonunu kestikten sonra kalan miktarı
 * güvenli bir şekilde (SafeERC20 kullanarak) hedef DEX/Protokol'e aktarır
 * ve arbitraj/swap işlemlerini yerine getirir.
 */
contract KletiaSmartRouter is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // Protokol Komisyon Oranı (Örn: 10 = %0.1, 100 = %1)
    // Payda (Denominator) = 10000
    uint256 public feeBasisPoints = 10; 
    address public feeTreasury;

    // --- GÜVENLİK YAMASI: Whitelist (Beyaz Liste) ---
    mapping(address => bool) public approvedTargets;

    event ExecutedERC20(address indexed tokenIn, uint256 grossAmount, uint256 feeAmount, address indexed targetProtocol);
    event ExecutedETH(uint256 grossAmount, uint256 feeAmount, address indexed targetProtocol);
    event FeeUpdated(uint256 newFeeBasisPoints);
    event TreasuryUpdated(address newTreasury);
    event TargetApproved(address indexed target, bool isApproved);

    modifier onlyApprovedTarget(address target) {
        require(approvedTargets[target], "Security: Target protocol is not whitelisted");
        _;
    }

    /**
     * @dev Constructor, varsayılan sahibi ve komisyon cüzdanını ayarlar.
     * @param _initialOwner Kontratın sahibi (Admin cüzdanı)
     * @param _feeTreasury Kesilen komisyonların gönderileceği cüzdan
     */
    constructor(address _initialOwner, address _feeTreasury) Ownable(_initialOwner) {
        require(_feeTreasury != address(0), "Treasury cannot be zero address");
        feeTreasury = _feeTreasury;
    }

    /**
     * @dev ETH İşlemleri için Yönlendirici
     * Komisyon anında kesilir ve treasury'ye yollanır, kalan miktar ile hedef protokol çağrılır.
     * @param targetProtocol İşlemin yapılacağı hedef protokol (Örn: Uniswap V2 Router)
     * @param targetCalldata Hedef protokole gönderilecek veri
     */
    function executeETH(address targetProtocol, bytes calldata targetCalldata) external payable nonReentrant whenNotPaused onlyApprovedTarget(targetProtocol) {
        require(msg.value > 0, "No ETH provided");
        require(targetProtocol != address(0), "Invalid target protocol");

        // Komisyon Hesabı
        uint256 feeAmount = (msg.value * feeBasisPoints) / 10000;
        uint256 netAmount = msg.value - feeAmount;

        // Komisyonu Treasury'e aktar
        if (feeAmount > 0) {
            (bool feeSuccess, ) = feeTreasury.call{value: feeAmount}("");
            require(feeSuccess, "Fee transfer failed");
        }

        // Ana işlemi hedef protokole yolla (Call - DelegateCall değil!)
        (bool success, bytes memory returnData) = targetProtocol.call{value: netAmount}(targetCalldata);

        if (!success) {
            // Revert sebebini kullanıcıya geri fırlat (Blockaid şeffaflığı)
            if (returnData.length > 0) {
                assembly {
                    let returnData_size := mload(returnData)
                    revert(add(32, returnData), returnData_size)
                }
            } else {
                revert("Target call failed");
            }
        }

        // Kalan (harcanmayan) ETH varsa kullanıcıya iade et
        uint256 remaining = address(this).balance;
        if (remaining > 0) {
            (bool refundSuccess, ) = msg.sender.call{value: remaining}("");
            require(refundSuccess, "Refund failed");
        }

        emit ExecutedETH(msg.value, feeAmount, targetProtocol);
    }

    /**
     * @dev ERC-20 İşlemleri için Yönlendirici
     * Kullanıcı bu kontrata "Approve" vermelidir.
     * @param tokenIn İşlem yapılacak giriş tokeni
     * @param totalAmount Toplam çekilecek miktar (Komisyon Dahil)
     * @param targetProtocol İşlemin yapılacağı hedef protokol (Örn: Uniswap V2 Router)
     * @param targetCalldata Hedef protokole gönderilecek veri
     */
    function executeERC20(
        address tokenIn,
        uint256 totalAmount,
        address targetProtocol,
        bytes calldata targetCalldata
    ) external nonReentrant whenNotPaused onlyApprovedTarget(targetProtocol) {
        require(totalAmount > 0, "Amount must be greater than zero");
        require(targetProtocol != address(0), "Invalid target protocol");
        require(tokenIn != address(0), "Invalid token address");

        IERC20 token = IERC20(tokenIn);

        // Kullanıcıdan tüm miktarı bu kontrata çek
        token.safeTransferFrom(msg.sender, address(this), totalAmount);

        // Komisyon Hesabı
        uint256 feeAmount = (totalAmount * feeBasisPoints) / 10000;
        uint256 netAmount = totalAmount - feeAmount;

        // Komisyonu Treasury'e gönder
        if (feeAmount > 0) {
            token.safeTransfer(feeTreasury, feeAmount);
        }

        // Kalan net miktarı hedef protokole onayla (Approve)
        token.forceApprove(targetProtocol, netAmount);

        // Hedef protokolü çağır (Kletia üzerinden)
        (bool success, bytes memory returnData) = targetProtocol.call(targetCalldata);

        if (!success) {
            // Revert sebebini kullanıcıya geri fırlat (Şeffaf hata tespiti)
            if (returnData.length > 0) {
                assembly {
                    let returnData_size := mload(returnData)
                    revert(add(32, returnData), returnData_size)
                }
            } else {
                revert("Target call failed");
            }
        }

        // İşlem bittikten sonra hedef protokoldeki allowance'ı sıfırla (Güvenlik standardı)
        token.forceApprove(targetProtocol, 0);

        // Kalan (harcanmayan) ERC20 tokeni varsa kullanıcıya iade et
        uint256 remaining = token.balanceOf(address(this));
        if (remaining > 0) {
            token.safeTransfer(msg.sender, remaining);
        }

        emit ExecutedERC20(tokenIn, totalAmount, feeAmount, targetProtocol);
    }

    // --- YÖNETİCİ (ADMIN) FONKSİYONLARI ---

    /**
     * @dev Güvenli hedef protokol ekleme / çıkarma (Sadece Owner)
     */
    function setApprovedTarget(address target, bool isApproved) external onlyOwner {
        require(target != address(0), "Invalid target address");
        approvedTargets[target] = isApproved;
        emit TargetApproved(target, isApproved);
    }

    function setFeeBasisPoints(uint256 _newFee) external onlyOwner {
        require(_newFee <= 500, "Fee cannot exceed 5% (500 bps)"); // Max %5
        feeBasisPoints = _newFee;
        emit FeeUpdated(_newFee);
    }

    function setFeeTreasury(address _newTreasury) external onlyOwner {
        require(_newTreasury != address(0), "Invalid treasury address");
        feeTreasury = _newTreasury;
        emit TreasuryUpdated(_newTreasury);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @dev Kontrata sıkışan tokenları kurtarmak için (Güvenlik Önlemi)
     */
    function rescueTokens(address tokenAddress, address to, uint256 amount) external onlyOwner {
        require(to != address(0), "Invalid destination");
        if (tokenAddress == address(0)) {
            (bool success, ) = to.call{value: amount}("");
            require(success, "ETH rescue failed");
        } else {
            IERC20(tokenAddress).safeTransfer(to, amount);
        }
    }

    // Kontratın ETH alabilmesi için
    receive() external payable {}
}

